import copperData from "../components/copper.json";
import brassData from "../components/brass.json";
import aluminumData from "../components/aluminum.json";
import stainlessData from "../components/stainless.json";
import miscData from "../components/misc.json";
import circuitBoardData from "../components/escrap.json";
import ramData from "../components/ram.json";
import cpuData from "../components/CPU.json";
import wholeData from "../components/WHOLE.json";

export const metals = [
  { id: "copper", title: "Copper", data: copperData },
  { id: "brass", title: "Brass", data: brassData },
  { id: "aluminum", title: "Aluminum", data: aluminumData },
  { id: "stainless", title: "Stainless Steel", data: stainlessData },
  { id: "misc", title: "Misc", data: miscData },
  { id: "boards", title: "Circuit Boards", data: circuitBoardData },
  { id: "ram", title: "RAM", data: ramData },
  { id: "cpus", title: "CPUs", data: cpuData },
  { id: "whole", title: "Whole Units", data: wholeData }
];
